import{_ as a,C as r,o as i,c as n,a5 as o,E as l,j as s,a as u}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Consulter les statistiques sur plusieurs dates","description":"","frontmatter":{"title":"Consulter les statistiques sur plusieurs dates","docId":"user.points.statistics","translationKey":"user.points.statistics","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"a7333d75baa9aec6e0c4afb69d1c773575a56ee8da982f0fa5a11a73b903ec2d","translationRevision":"c7716c33d0e7770701883e19c813694b26c7931bc4f388146508d67a89ac3aeb","order":20},"headers":[],"relativePath":"fr/user/points/statistics.md","filePath":"fr/user/points/statistics.md","lastUpdated":1794611623000}'),d={name:"fr/user/points/statistics.md"};function c(p,e,m,f,h,v){const t=r("DemoFrame");return i(),n("div",null,[e[0]||(e[0]=o('<h1 id="review-statistics-across-dates" tabindex="-1">Consulter les statistiques sur plusieurs dates <a class="header-anchor" href="#review-statistics-across-dates" aria-label="Permalink to &quot;Consulter les statistiques sur plusieurs dates {#review-statistics-across-dates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Comparer l’activité d’un créateur sur une période pertinente et comprendre pourquoi les totaux diffèrent du flux visible ou du solde de points. Il faut de l’activité enregistrée dans l’installation locale et le bon créateur sélectionné via <a href="./../live/connections.html">Connections</a>. La connexion Cloud n’est pas la source de ces statistiques locales.</p><h2 id="query-the-recorded-period" tabindex="-1">Interroger la période enregistrée <a class="header-anchor" href="#query-the-recorded-period" aria-label="Permalink to &quot;Interroger la période enregistrée {#query-the-recorded-period}&quot;">​</a></h2><ol><li>Ouvrez <strong>Analytics</strong> et vérifiez le créateur affiché à côté des commandes de dates. Le créateur sélectionné détermine les agrégats stockés qui seront interrogés.</li><li>Choisissez <strong>Today</strong>, <code>7d</code>, <code>30d</code>, <code>90d</code> ou une période personnalisée. Pour des dates personnalisées, fixez explicitement le début et la fin et vérifiez leur ordre.</li><li>Lisez la période affichée et le nombre de sessions avant de comparer les résultats. Les limites des dates locales utilisent un décalage de fuseau horaire ; changer le fuseau de l’ordinateur peut modifier l’interprétation d’une période.</li><li>Sélectionnez la métrique nécessaire : discussions, cadeaux, mentions J’aime, diamants ou pic de spectateurs. Comparez les périodes avec les graphiques d’activité et examinez les meilleurs spectateurs renvoyés dans le tableau des contributeurs.</li><li>Recherchez dans ce tableau un spectateur déjà présent dans les données renvoyées. Il ne s’agit pas d’une recherche illimitée de tous les spectateurs jamais observés.</li><li>Sélectionnez <strong>Refresh</strong> après une nouvelle activité ou à votre retour sur la page. Notez le créateur, les dates et la métrique avec tout chiffre partagé.</li></ol><p>La page actuelle appelle l’opération native <code>analytics.summary</code> avec un créateur et une période. Elle lit des agrégats persistants, y compris les sessions enregistrées précédemment ; elle n’est pas limitée aux événements encore conservés dans le flux actuel. La base analytique stocke des agrégats plutôt qu’une transcription des discussions.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les statistiques locales persistantes et les requêtes par période sont disponibles. Des dates sans activité renvoient légitimement un résultat vide. Les soldes de points peuvent différer car les <a href="./rules.html">taux d’attribution</a>, ajustements manuels et récompenses d’automatisation représentent une mesure différente. Diamants, nombres de cadeaux et points ne sont pas des unités interchangeables.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Si les données semblent absentes, effacez la recherche de contributeur, élargissez la période, confirmez le créateur et actualisez. Après une erreur de l’hôte, conservez son code de diagnostic et réessayez une fois la connexion rétablie. Effacer le flux ne supprime pas les statistiques. Un nouveau répertoire de données n’a aucun historique antérieur ; utilisez des <a href="./../preferences/backups.html">sauvegardes</a> pour déplacer une installation.</p>',10)),l(t,{scenario:"analytics",locale:"fr",title:"Démo : statistiques"}),e[1]||(e[1]=s("h2",{id:"operational-details",tabindex:"-1"},[u("Détails de fonctionnement "),s("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Détails de fonctionnement {#operational-details}"'},"​")],-1)),e[2]||(e[2]=s("p",null,"Analytics demande actuellement les 10 principaux contributeurs pour le créateur et les dates choisis. La recherche filtre ce sous-ensemble, sans rechercher tous les spectateurs. Ces agrégats persistants ont une période et une unité différentes des diamants/likes de la session et des soldes de points. Conservez créateur, dates et mesure lors des exports et comparaisons.",-1))])}const q=a(d,[["render",c]]);export{g as __pageData,q as default};
